{
  "cvars": {
    "ivs": [
      {
        "description": "Whether the Reader View layout was activated for the trial (binary treatment). Coded 1 = Reader View ON, 0 = Reader View OFF.",
        "columns": [
          "reader_view"
        ]
      }
    ],
    "dv": {
      "description": "Log-transformed reading speed (dependent variable). We use log(speed + 1) to reduce positive skew and stabilize variance across trials.",
      "columns": [
        "log_speed"
      ]
    },
    "controls": [
      {
        "description": "Dyslexia status (binary moderator). dyslexia_bin indicates presence of dyslexia (1) vs no dyslexia (0). This is the subgrouping of interest and will be tested as a moderator of the Reader View effect.",
        "is_moderator": true,
        "moderator_on": "reader_view",
        "columns": [
          "dyslexia_bin"
        ]
      },
      {
        "description": "Participant age (centered). Continuous covariate (age centered to the sample mean).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "age_c"
        ]
      },
      {
        "description": "Number of words on the page (centered). Controls for text length which strongly affects reading time.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "num_words_c"
        ]
      },
      {
        "description": "Flesch-Kincaid readability score (centered). Controls for text difficulty.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "Flesch_c"
        ]
      },
      {
        "description": "Comprehension correctness rate on page (proportion correct). Controls for effort/accuracy tradeoffs.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "correct_rate"
        ]
      },
      {
        "description": "Indicator that this trial was a retake (1) vs first attempt (0).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "retake_trial"
        ]
      },
      {
        "description": "Native English speaker indicator mapped to binary (1 = native English 'Y', 0 = not native 'N').",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "english_native_bin"
        ]
      },
      {
        "description": "Image width on the page (centered). Controls for layout effects that could influence reading flow.",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "img_width_c"
        ]
      },
      {
        "description": "Device used for the trial (categorical). Kept as the raw column and included as a categorical control in the model (C(device)).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "device"
        ]
      },
      {
        "description": "Gender of the reader (categorical). Included as a categorical control (C(gender)).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender"
        ]
      },
      {
        "description": "Page identifier (categorical). Includes potential text-specific fixed effects (C(page_id)).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "page_id"
        ]
      },
      {
        "description": "Participant unique id used as a grouping variable for random intercepts (repeated measures).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "uuid"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Make a copy to avoid side-effects\n    df = df.copy()\n\n    # Required columns for analysis\n    req_cols = ['uuid', 'reader_view', 'dyslexia_bin', 'speed', 'age', 'num_words',\n                'Flesch_Kincaid', 'correct_rate', 'retake_trial', 'english_native',\n                'img_width', 'device', 'gender', 'page_id']\n\n    # Drop rows missing essential variables\n    df = df.dropna(subset=['uuid', 'reader_view', 'dyslexia_bin', 'speed'])\n\n    # Coerce numeric columns (if they come in as strings)\n    numeric_cols = ['reader_view', 'dyslexia_bin', 'speed', 'age', 'num_words', 'Flesch_Kincaid',\n                    'correct_rate', 'retake_trial', 'img_width']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # After coercion, drop rows missing any numeric control required for the model\n    needed_after_coercion = ['speed', 'reader_view', 'dyslexia_bin', 'num_words', 'Flesch_Kincaid', 'age']\n    df = df.dropna(subset=needed_after_coercion)\n\n    # Ensure binary encodings are integers\n    df['reader_view'] = df['reader_view'].astype(int)\n    df['dyslexia_bin'] = df['dyslexia_bin'].astype(int)\n    df['retake_trial'] = df['retake_trial'].fillna(0).astype(int)\n\n    # Create dependent variable: log-transformed speed to stabilize variance and reduce skew\n    # Add a small constant to avoid log(0)\n    df['log_speed'] = np.log(df['speed'].clip(lower=0) + 1)\n\n    # Center continuous covariates to improve interpretability of main effects\n    df['age_c'] = df['age'] - df['age'].mean()\n    df['num_words_c'] = df['num_words'] - df['num_words'].mean()\n    df['Flesch_c'] = df['Flesch_Kincaid'] - df['Flesch_Kincaid'].mean()\n    df['img_width_c'] = df['img_width'] - df['img_width'].mean()\n\n    # Map english_native to binary 1/0 if present\n    if 'english_native' in df.columns:\n        df['english_native_bin'] = df['english_native'].astype(str).str.upper().map({'Y': 1, 'N': 0})\n        # If there are other values, treat them as missing\n        df['english_native_bin'] = df['english_native_bin'].fillna(0).astype(int)\n    else:\n        df['english_native_bin'] = 0\n\n    # Coerce categorical columns to appropriate dtype for modeling (we will use C(...) in formula)\n    for c in ['device', 'gender', 'page_id', 'uuid']:\n        if c in df.columns:\n            df[c] = df[c].astype('category')\n\n    # Keep only rows with at least one reading trial per participant (uuid) and necessary columns\n    final_cols = ['uuid', 'page_id', 'reader_view', 'log_speed', 'dyslexia_bin', 'age_c', 'num_words_c',\n                  'Flesch_c', 'correct_rate', 'retake_trial', 'english_native_bin', 'img_width_c',\n                  'device', 'gender']\n    df = df.dropna(subset=['log_speed'])\n\n    # Return dataframe with columns needed for modeling (may contain other columns as well)\n    return df\n",
  "m_code": "def model(df: pd.DataFrame):\n    \"\"\"\n    Fit a mixed-effects linear model testing whether Reader View (reader_view)\n    improves reading speed for individuals with dyslexia (dyslexia_bin). We\n    include an interaction reader_view * dyslexia_bin to test differential effects\n    and include participant random intercepts to account for repeated measures.\n\n    Model specification (formula):\n      log_speed ~ reader_view * dyslexia_bin + age_c + num_words_c + Flesch_c +\n                  correct_rate + retake_trial + english_native_bin + img_width_c +\n                  C(device) + C(gender) + C(page_id)\n\n    Random effects: random intercept for uuid (groups=df['uuid']).\n\n    Returns\n    -------\n    results : statsmodels mixedlm results object\n    \"\"\"\n    import statsmodels.formula.api as smf\n\n    # Ensure required columns exist\n    required = ['log_speed', 'reader_view', 'dyslexia_bin', 'uuid']\n    for c in required:\n        if c not in df.columns:\n            raise ValueError(f\"Required column {c} not present in dataframe\")\n\n    # Define formula with interaction between reader_view and dyslexia_bin\n    formula = (\n        'log_speed ~ reader_view * dyslexia_bin + age_c + num_words_c + Flesch_c + '\n        'correct_rate + retake_trial + english_native_bin + img_width_c + '\n        'C(device) + C(gender) + C(page_id)'\n    )\n\n    # Fit mixed effects model with random intercept for participant (uuid)\n    # Use REML=False for easier comparison with frequentist fixed-effect output\n    md = smf.mixedlm(formula, data=df, groups=df['uuid'], re_formula='1')\n    try:\n        mdf = md.fit(reml=False, method='lbfgs')\n    except Exception:\n        # fallback to default method if convergence issues\n        mdf = md.fit(reml=False)\n\n    # Print summary to help interpretation in interactive use\n    print(mdf.summary())\n\n    return mdf\n"
}

